<script setup>
import {ref,onMounted,onUnmounted,defineAsyncComponent} from 'vue';
import brand from './brand.json';
const App=defineAsyncComponent(()=>import('./App.vue'));
const accepted=ref(false),loaded=ref(false),agreed=ref(false),busy=ref(false),error=ref(''),version=ref('');
let alive=true;
async function api(action,payload){const response=await window.pywebview.api.usage_consent(action,payload);if(!response.ok)throw Error(response.error||'无法保存使用说明确认');return response.data}
async function check(){if(busy.value)return;busy.value=true;error.value='';try{const state=await api('status');if(!alive)return;version.value=state.version;accepted.value=state.accepted;loaded.value=true}catch(e){error.value='无法读取使用说明确认记录：'+e.message}finally{busy.value=false}}
async function accept(){if(!agreed.value||busy.value)return;busy.value=true;error.value='';try{const state=await api('accept',{agreed:true,version:version.value});if(!state.accepted)throw Error('同意记录未保存，请重试');accepted.value=true}catch(e){error.value='保存失败，尚未进入软件：'+e.message}finally{busy.value=false}}
async function decline(){busy.value=true;try{await api('decline')}catch(e){error.value=e.message}finally{busy.value=false}}
function bridgeReady(){check()}
onMounted(()=>{window.addEventListener('pywebviewready',bridgeReady);if(window.pywebview?.api)check()});
onUnmounted(()=>{alive=false;window.removeEventListener('pywebviewready',bridgeReady)});
</script>
<template><App v-if="accepted"/><main v-else class="first-use-page"><section class="first-use-panel" role="dialog" aria-modal="true" aria-labelledby="first-use-title"><header><span class="first-use-eyebrow">{{brand.name}} · 首次使用</span><h1 id="first-use-title">使用须知</h1><p>开始前，请了解软件的功能边界与数据保存方式。</p></header><article v-if="loaded" class="first-use-copy" tabindex="0" aria-label="使用说明正文"><section class="free-notice"><h2>本软件完全免费，请勿购买</h2><p>本软件不收取下载费、使用费或解锁费，无需付费购买激活码、会员或授权。请通过作者提供的正式发布渠道获取。</p><p>禁止未经作者授权倒卖本软件，或将其改名、打包后以收费软件形式出售。若有人以本软件名义向你收费，请勿付款，并向相应平台举报。</p></section><section class="account-risk"><h2>重要：账号安全与封禁风险</h2><p><strong>使用本软件，尤其是客户端读取、代理或设备隔离等实验功能，可能触发游戏运营方的安全检测或违反其使用规则，导致警告、限制登录、临时或永久封禁，以及账号数据、虚拟物品或相关财产损失。</strong></p><p>软件免费、未自动战斗、读取成功或此前使用正常，均不代表获得游戏官方许可，也不代表以后不会受罚。作者无法控制运营方的风控与处罚决定，不提供账号不被封禁、账号恢复或免受损失的保证。若不能接受上述风险，请选择不同意并退出，不要启用相关功能。</p></section><h2>功能说明与风险提示</h2><p>本软件是非官方的阴阳师角色、启动方案和本地记录管理工具，与游戏开发及运营方无隶属关系。请仅管理你有权使用的账号，并遵守游戏及相关平台的规则。</p><p>客户端数据读取、代理和设备隔离等功能仍属实验性质。读取功能会向游戏进程加载临时组件，可能受游戏版本及客户端状态影响，出现读取不完整、结果不准确、连接失败或客户端异常，也不能保证账号安全。请自行决定是否启用这些功能。</p><h2>数据保存与更新说明</h2><p>账号缓存、角色配置、资源记录及本次同意记录保存在本机软件目录中，通常位于 data 文件夹。请妥善保管并备份，不要向他人提供包含个人缓存或代理凭证的文件。更换或删除数据目录后，软件可能再次要求确认。</p><p>检查和下载更新会访问配置的发行平台。升级前请保存方案并备份个人数据；遇到异常可停止使用相关实验功能。</p><h2>免责声明与责任边界</h2><p>你应确认自己有权使用相关账号，了解并遵守适用法律及游戏、平台规则，自主决定是否使用本软件。不得借助本软件侵害他人权益或实施违法行为；因自身违法违规、擅自修改软件或泄露个人缓存与凭证产生的责任，依法由相应责任方承担。</p><p>对于游戏运营方独立作出的风控或处罚、第三方服务异常、用户自身操作等原因造成的封号、账号或虚拟财产损失，作者在依法不应承担责任的范围内不承担赔偿责任。</p><p>记录和提醒仅供辅助核对，不保证实时、完整或准确。是否完成任务、领取奖励及冷却状态，请以游戏内显示为准。</p><p>你可以选择不同意并退出；同意后才会进入主界面。同意本说明不会剥夺你依法享有的权利。</p></article><p v-else class="first-use-loading">正在连接本地软件…</p><p v-if="error" class="first-use-error" role="alert">{{error}} <button v-if="!loaded" @click="check" :disabled="busy">重试</button></p><footer><label><input type="checkbox" v-model="agreed" :disabled="!loaded||busy">我已阅读使用须知，理解账号封禁及损失风险，并同意相关条款</label><div><small>说明版本 {{version||'加载中'}} · 同意记录仅保存在本机</small><button @click="decline" :disabled="busy">不同意并退出</button><button class="first-use-accept" @click="accept" :disabled="!loaded||!agreed||busy">{{busy?'处理中…':'同意并进入'}}</button></div></footer></section></main></template>
<style scoped>
.first-use-page{height:100dvh;box-sizing:border-box;display:flex;align-items:center;justify-content:center;padding:28px;background:#f4efe5;color:#3d382f}.first-use-panel{width:760px;max-width:100%;max-height:100%;display:flex;flex-direction:column;background:#fffcf6;border:1px solid #deceb6;border-radius:14px;box-shadow:0 15px 50px #65492c12;overflow:hidden}.first-use-panel header{padding:26px 30px 18px;border-bottom:1px solid #e8dfd0}.first-use-eyebrow{font-size:12px;color:#8a7459}.first-use-panel h1{font-size:24px;margin:8px 0}.first-use-panel header p{font-size:13px;color:#8d7d66;margin:0}.first-use-copy{overflow:auto;min-height:0;padding:4px 30px 16px;line-height:1.8;font-size:13px;overscroll-behavior:contain}.first-use-copy h2{font-size:14px;margin:18px 0 5px}.first-use-copy p{margin:0 0 8px;color:#645b4d}.first-use-panel footer{flex:none;padding:18px 30px 22px;border-top:1px solid #e8dfd0}.first-use-panel footer label{display:flex;align-items:flex-start;gap:8px;font-size:13px;cursor:pointer}.first-use-panel input{margin-top:4px;accent-color:#785e42}.first-use-panel footer>div{display:flex;align-items:center;gap:10px;margin-top:16px;flex-wrap:wrap}.first-use-panel small{font-size:11px;color:#95836b;flex:1}.first-use-panel button{border:1px solid #d8c8b1;border-radius:6px;padding:9px 14px;background:#fffcf6;color:#6e573f;cursor:pointer;font:inherit;font-size:13px}.first-use-panel .first-use-accept{background:#775d42;color:#fffaf0;border-color:#775d42}.first-use-panel button:disabled{opacity:.4;cursor:default}.first-use-error{color:#a54235;font-size:12px;padding:0 30px}.first-use-loading{padding:30px}@media(max-width:650px){.first-use-page{padding:12px}.first-use-panel header,.first-use-panel footer{padding:18px}.first-use-copy{padding:0 18px 12px}.first-use-panel small{flex-basis:100%}}
.free-notice{margin-top:18px;padding:12px 16px;background:#f2ecdf;border:1px solid #e1d3ba;border-radius:8px}.free-notice h2{margin:0 0 6px;color:#715537}.free-notice p:last-child{margin-bottom:0}
.account-risk{margin-top:18px;padding:12px 16px;background:#faf0e9;border:1px solid #dec0a9;border-left:3px solid #b4774c;border-radius:8px}.account-risk h2{margin:0 0 6px;color:#874a30}.account-risk p:last-child{margin-bottom:0}
</style>
